def encode_cyclic(s: str):
    """
    returns encoded string by cycling groups of three characters.
    """
    # split string to groups. Each of length 3.
    groups = [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]
    # cycle elements in each group. Unless group has fewer elements than 3.
    groups = [(group[1:] + group[0]) if len(group) == 3 else group for group in groups]
    return "".join(groups)


def decode_cyclic(s: str):
    """
    takes as input string encoded with encode_cyclic function. Returns decoded string.
    """
    # combine cycles from groups
    def combine_cycles(groups):
        result = []
        for i in range(0, len(s), 3):
            group = groups[i // 3]
            cycle = group + group[0]
            result.append(cycle[i:i+3])
        return ''.join(result)

    # decode function
    # splitting combined cycles back into original groups, decoding them
    def decode_combined(cs):
        result = [''] * len(s)
        groups = [cs[i:i+3] for i in range(0, len(cs), 3)]
        for i in range(len(groups) // 3):
            group = groups[i * 3]
            cycle = group[0]
            for j in range(3):
                result[i * 3 + j] = group[j][1:]
        return ''.join(result)

    return combine_cycles([decode_cyclic(s[:3 * 3 + i]) for i in range((len(s) + 2) // 3)])
