def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters.

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = "aeiou"
    encoded_message = ""
    for char in message:
        if char.isalpha():
            # Swap case
            char = char.swapcase()
            # Find the new character if it's a vowel
            for i, v in enumerate(vowels):
                if v == char:
                    # Replace vowel with the vowel that appears 2 positions ahead
                    if char == 'a':
                        char = 'c'
                    elif char == 'A':
                        char = 'C'
                    elif char == 'e':
                        char = 'g'
                    elif char == 'E':
                        char = 'G'
                    elif char == 'i':
                        char = 'k'
                    elif char == 'I':
                        char = 'K'
                    elif char == 'o':
                        char = 'q'
                    elif char == 'O':
                        char = 'Q'
                    elif char == 'u':
                        char = 'w'
                    elif char == 'U':
                        char = 'W'
                    break
        encoded_message += char
    return encoded_message
