def skjkasdkd(lst):
    """Function to find the largest prime number in the list and return the sum of its digits.

    Args:
    lst (list): A list of integers.

    Returns:
    int: The sum of the digits of the largest prime in the list.
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_prime = -1
    for num in lst:
        if num > largest_prime and is_prime(num):
            largest_prime = num

    def sum_of_digits(n):
        """Return the sum of the digits of the given number."""
        return sum(int(digit) for digit in str(n))

    return sum_of_digits(largest_prime)
