def find_max(words):
    def unique_chars_count(word):
        return len(set(word))

    if not words:
        return ""

    max_len = 0
    max_word = ""

    for word in words:
        if unique_chars_count(word) > max_len:
            max_len = unique_chars_count(word)
            max_word = word
        elif unique_chars_count(word) == max_len:
            # If equal unique characters count, maintain lexicographical order
            if word < max_word:
                max_word = word

    return max_word
